import { useContext, useEffect, useState } from 'react';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

function Dashboard() {
  const { user } = useContext(AuthContext);
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    async function load() {
      try {
        const res = await axios.get('http://localhost:5001/api/resume/my', { withCredentials: true });
        setResumes(res.data.data);
      } catch (err) {
        console.error(err);
      }
    }
    if (user) load();
  }, [user]);

  if (!user) return <div style={{ padding: 20 }}>Please login to view your dashboard</div>;

  return (
    <div className="page mt-10">
      <div className="container">
        <header className="mb-6">
          <h3 className="text-2xl">{user.name || user.email}'s Dashboard</h3>
          <p className="muted">Track your applications and match results.</p>
        </header>

        <div className="max-w-4xl mx-auto">
          {resumes.length === 0 ? (
            <div className="card text-center py-10">
              <p className="muted">No resumes uploaded yet. Start by uploading your profile.</p>
            </div>
          ) : (
            <div className="flex flex-col gap-4">
              {resumes.map(r => (
                <div key={r._id} className="card p-6 border-l-4 hover-shadow transition-all" style={{ borderLeftColor: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? '#f59e0b' : 'var(--danger)') }}>
                  <div className="flex flex-col md:flex-row justify-between gap-6">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-3">
                        <span className={`badge ${r.score >= 70 ? 'bg-success' : (r.score >= 40 ? 'bg-info' : 'bg-danger')}`}>
                          Match Score: {Math.round(r.score || 0)}%
                        </span>
                        <span className="badge bg-secondary">{r.interviewStatus}</span>
                        {r.jobId?.title && <span className="badge bg-secondary">For: {r.jobId.title}</span>}
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
                          <strong className="block text-xs muted mb-1 uppercase tracking-tight">Matched Skills</strong>
                          <div className="flex flex-wrap gap-1">
                            {(r.matchedSkills || r.skills || []).map((s, i) => (
                              <span key={i} className="badge bg-secondary">{s}</span>
                            ))}
                          </div>
                        </div>
                        <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
                          <strong className="block text-xs muted mb-1 uppercase tracking-tight">Missing Skills</strong>
                          <div className="flex flex-wrap gap-1">
                            {(r.missingSkills || []).length > 0 ? (
                              (r.missingSkills || []).map((s, i) => (
                                <span key={i} className="badge bg-secondary missing">{s}</span>
                              ))
                            ) : (
                              <span className="text-sm muted">None identified</span>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>

                    <div className="flex flex-col justify-center gap-2" style={{ minWidth: '140px' }}>
                      <p className="muted text-xs text-center">{r.createdAt ? new Date(r.createdAt).toLocaleDateString() : ''}</p>
                      <button className="btn btn-ghost w-full">View Details</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
